function fwCreate(n){
  return { n:n, tree:new Array(n+1).fill(0) };
}
function fwBuild(arr){
  var fw=fwCreate(arr.length);
  for(var i=0;i<arr.length;i++) fwUpdate(fw, i, arr[i]);
  return fw;
}
function fwUpdate(fw, i, delta){
  if(i<0||i>=fw.n) throw new Error('index out of range: '+i);
  for(var x=i+1;x<=fw.n;x+=x&(-x)) fw.tree[x]+=delta;
  return fw;
}
function fwPrefix(fw, i){
  if(i<0) return 0;
  if(i>=fw.n) i=fw.n-1;
  var s=0;
  for(var x=i+1;x>0;x-=x&(-x)) s+=fw.tree[x];
  return s;
}
function fwRange(fw, l, r){
  if(l>r) return 0;
  return fwPrefix(fw, r)-fwPrefix(fw, l-1);
}
function fwGet(fw, i){
  return fwRange(fw, i, i);
}
function fwToArray(fw){
  var out=[];
  for(var i=0;i<fw.n;i++) out.push(fwGet(fw,i));
  return out;
}
function fwLowerBound(fw, target){
  var pos=0, rem=target, log=1;
  while((log<<1)<=fw.n) log<<=1;
  for(var step=log;step>0;step>>=1){
    if(pos+step<=fw.n && fw.tree[pos+step]<rem){
      pos+=step; rem-=fw.tree[pos];
    }
  }
  return pos<fw.n?pos:-1;
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { fwCreate:fwCreate, fwBuild:fwBuild, fwUpdate:fwUpdate, fwPrefix:fwPrefix,
    fwRange:fwRange, fwGet:fwGet, fwToArray:fwToArray, fwLowerBound:fwLowerBound };
}
if (typeof window !== 'undefined') {
  window.FenwickForgePure = { fwCreate:fwCreate, fwBuild:fwBuild, fwUpdate:fwUpdate, fwPrefix:fwPrefix,
    fwRange:fwRange, fwGet:fwGet, fwToArray:fwToArray, fwLowerBound:fwLowerBound };
}
